  "objectives": [
    {
      "label": "Request an appointment",
      "description": "Peça para marcar uma consulta médica."
    },
    {
      "label": "Describe your symptoms",
      "description": "Explique que está com o nariz entupido e a garganta arranhando."
    },
    {
      "label": "Say when they started",
      "description": "Diga há quanto tempo está com esses sintomas."
    }
  ],
  "openingLine": "Hi, this is Emma at Oak Street Family Clinic. How can I help today?",
  "hints": [
    "I'd like to make an appointment, please.",
    "Do you have anything available today?",
    "I have a stuffy nose and a scratchy throat.",
    "They started yesterday."
  ]
}

{
  "title": "Combinar um passeio",
  "situation": "Sua amiga Emma liga para conversar sobre o fim de semana. Convide-a para fazer algo e combinem um dia, um horário e um lugar.",
